mapper.select:
INSERT INTO beat_instance (
    run_id, seq, source, asset_id, arc_id, arc_seg_no, beat_type,
    pacing, chapter_no, volume_no, filled_text, status,
    beat_key, chapter_seq, pack_version, novelty_key, story_layer, beat_role, route_contract, plan_revision
) VALUES (
    #{p.runId}, #{p.seq}, #{p.source}, #{p.assetId}, #{p.arcId}, #{p.arcSegNo}, #{p.beatType},
    #{p.pacing}, #{p.chapterNo}, #{p.volumeNo}, #{p.filledText}, #{p.status},
    #{p.beatKey}, #{p.chapterSeq}, #{p.packVersion}, #{p.noveltyKey}, #{p.storyLayer}, #{p.beatRole}, #{p.routeContract}::jsonb, #{p.planRevision,jdbcType=INTEGER}
)
RETURNING id

mapper.update:
UPDATE beat_instance
SET filled_text = #{filledText},
    status = #{status},
    updated_time = NOW()
WHERE run_id = #{runId}
  AND beat_key = #{beatKey}
  AND plan_revision = #{planRevision}
  AND EXISTS (
      SELECT 1 FROM run r
      WHERE r.id = #{runId}
        AND r.active_plan_revision = #{planRevision}
  )

mapper.delete:
DELETE FROM beat_instance
WHERE run_id = #{runId}
  AND volume_no = #{volumeNo}
